-- order_items (sample — first 5 catalog items)
INSERT INTO public.order_items (order_id, itemname, pgno, scoopin, qty, rate, itemtotal, comments)
SELECT o.id, v.itemname, v.pgno, v.scoopin, v.qty::numeric, v.rate::numeric, v.itemtotal::numeric, v.comments
FROM (VALUES
    ('SEED-B001', 'staff rice', '4', 'staff rice_gm_in', 1, 100, 100, 'Seed from catalog.js'),
    ('SEED-B002', 'tea powder', '6B', 'staff rice_gm_in', 2, 110, 220, 'Seed from catalog.js'),
    ('SEED-B003', 'oil tin', '7', 'staff rice_gm_in', 3, 120, 360, 'Seed from catalog.js'),
    ('SEED-B004', 'chilly powder', '10', 'staff rice_gm_in', 4, 130, 520, 'Seed from catalog.js'),
    ('SEED-B005', 'haldi powder', '11', 'staff rice_gm_in', 5, 140, 700, 'Seed from catalog.js')
) AS v(billno, itemname, pgno, scoopin, qty, rate, itemtotal, comments)
JOIN public.orders o ON o.billno = v.billno
WHERE NOT EXISTS (
    SELECT 1 FROM public.order_items oi WHERE oi.order_id = o.id AND oi.itemname = v.itemname
);

-- inventory_out (sample — first 5 categories)
INSERT INTO public.inventory_out (category, dt, tm, issuedto, commontag, totalqty)
SELECT v.category, v.dt::date, v.tm, v.issuedto, v.commontag, v.totalqty::numeric
FROM (VALUES
    ('INDIAN', '2025-09-01', '10:00', 'Line 1', 'SEED-OUT-001', 100),
    ('CHINESE', '2025-09-02', '10:10', 'Line 2', 'SEED-OUT-002', 200),
    ('CONTINENTAL', '2025-09-03', '10:20', 'Line 3', 'SEED-OUT-003', 300),
    ('TANDOOR', '2025-09-04', '10:30', 'Line 4', 'SEED-OUT-004', 400),
    ('DEEP_FRIDGE1', '2025-09-05', '10:40', 'Line 5', 'SEED-OUT-005', 500)
) AS v(category, dt, tm, issuedto, commontag, totalqty)
WHERE NOT EXISTS (SELECT 1 FROM public.inventory_out io WHERE io.commontag = v.commontag);

-- inventory_out_items (sample)
INSERT INTO public.inventory_out_items (inventory_out_id, itemname, pgno, scoop_out, qty, comments)
SELECT io.id, v.itemname, v.pgno, v.scoop_out, v.qty::numeric, v.comments
FROM (VALUES
    ('SEED-OUT-001', 'staff rice', '4', 'staff rice_gm_out', 50, 'Seed from catalog.js'),
    ('SEED-OUT-002', 'tea powder', '6B', 'staff rice_gm_out', 60, 'Seed from catalog.js'),
    ('SEED-OUT-003', 'oil tin', '7', 'staff rice_gm_out', 70, 'Seed from catalog.js'),
    ('SEED-OUT-004', 'chilly powder', '10', 'staff rice_gm_out', 80, 'Seed from catalog.js'),
    ('SEED-OUT-005', 'haldi powder', '11', 'staff rice_gm_out', 90, 'Seed from catalog.js')
) AS v(commontag, itemname, pgno, scoop_out, qty, comments)
JOIN public.inventory_out io ON io.commontag = v.commontag
WHERE NOT EXISTS (
    SELECT 1 FROM public.inventory_out_items ioi WHERE ioi.inventory_out_id = io.id AND ioi.itemname = v.itemname
);

-- order_entries (sample flat in — first 5 catalog items)
INSERT INTO public.order_entries (vendor, dt, billno, itemname, pgno, scoopin, qty, rate, itemtotal, comments)
SELECT v.vendor, v.dt::date, v.billno, v.itemname, v.pgno, v.scoopin, v.qty::numeric, v.rate::numeric, v.itemtotal::numeric, v.comments
FROM (VALUES
    ('KiranaShreeGanesh', '2025-09-10', 'SEED-FLAT-01', 'staff rice', '4', 'staff rice_gm_in', 1, 120, 120, 'Seed from catalog.js'),
    ('RS Sales', '2025-09-10', 'SEED-FLAT-02', 'tea powder', '6B', 'staff rice_gm_in', 2, 125, 250, 'Seed from catalog.js'),
    ('Royal Food', '2025-09-10', 'SEED-FLAT-03', 'oil tin', '7', 'staff rice_gm_in', 3, 130, 390, 'Seed from catalog.js'),
    ('MilkAndCurd', '2025-09-10', 'SEED-FLAT-04', 'chilly powder', '10', 'staff rice_gm_in', 4, 135, 540, 'Seed from catalog.js'),
    ('PaneerParasDairy', '2025-09-10', 'SEED-FLAT-05', 'haldi powder', '11', 'staff rice_gm_in', 5, 140, 700, 'Seed from catalog.js')
) AS v(vendor, dt, billno, itemname, pgno, scoopin, qty, rate, itemtotal, comments)
WHERE NOT EXISTS (
    SELECT 1 FROM public.order_entries oe
    WHERE oe.vendor = v.vendor AND oe.dt = v.dt::date AND oe.billno = v.billno
      AND oe.itemname = v.itemname AND oe.pgno = v.pgno
);

-- order_out (sample flat out)
INSERT INTO public.order_out (category, dt, "time", itemname, "pgNo", scoop_out, qty, comments)
SELECT v.category, v.dt::date, v."time", v.itemname, v."pgNo", v.scoop_out, v.qty::numeric, v.comments
FROM (VALUES
    ('INDIAN', '2025-09-10', '09:00', 'staff rice', '4', 'staff rice_gm_out', 25, 'Seed from catalog.js'),
    ('CHINESE', '2025-09-10', '09:10', 'tea powder', '6B', 'staff rice_gm_out', 30, 'Seed from catalog.js'),
    ('CONTINENTAL', '2025-09-10', '09:20', 'oil tin', '7', 'staff rice_gm_out', 35, 'Seed from catalog.js'),
    ('TANDOOR', '2025-09-10', '09:30', 'chilly powder', '10', 'staff rice_gm_out', 40, 'Seed from catalog.js'),
    ('DEEP_FRIDGE1', '2025-09-10', '09:40', 'haldi powder', '11', 'staff rice_gm_out', 45, 'Seed from catalog.js')
) AS v(category, dt, "time", itemname, "pgNo", scoop_out, qty, comments)
WHERE NOT EXISTS (
    SELECT 1 FROM public.order_out oo
    WHERE oo.itemname = v.itemname AND oo."pgNo" = v."pgNo"
      AND oo.scoop_out = v.scoop_out AND oo.dt = v.dt::date AND oo."time" = v."time"
);

-- recipe_entries (sample — first 5 dishes + catalog items)
INSERT INTO public.recipe_entries (dishname, dishcode, reciepeitemname, "pgNo", receipescoop, qty, "inGm", "inML", "inPiece", comments)
SELECT v.dishname, v.dishcode, v.reciepeitemname, v."pgNo", v.receipescoop, v.qty::numeric, v."inGm"::numeric, v."inML", v."inPiece", v.comments
FROM (VALUES
    ('CHOLE  KULCHE', 'D001', 'staff rice', '4', 'staff rice_gm_reciepe', 100, 100, NULL::numeric, NULL::numeric, 'Seed from catalog.js'),
    ('CHOLE BHATURE', 'D002', 'tea powder', '6B', 'staff rice_gm_reciepe', 125, 125, NULL::numeric, NULL::numeric, 'Seed from catalog.js'),
    ('PINDI  CHOLE', 'D003', 'oil tin', '7', 'staff rice_gm_reciepe', 150, 150, NULL::numeric, NULL::numeric, 'Seed from catalog.js'),
    ('EXTRA  KULCHA', 'D004', 'chilly powder', '10', 'staff rice_gm_reciepe', 175, 175, NULL::numeric, NULL::numeric, 'Seed from catalog.js'),
    ('ONION PARATHA', 'D005', 'haldi powder', '11', 'staff rice_gm_reciepe', 200, 200, NULL::numeric, NULL::numeric, 'Seed from catalog.js')
) AS v(dishname, dishcode, reciepeitemname, "pgNo", receipescoop, qty, "inGm", "inML", "inPiece", comments)
WHERE NOT EXISTS (
    SELECT 1 FROM public.recipe_entries re
    WHERE re.dishname = v.dishname AND re.reciepeitemname = v.reciepeitemname
      AND re.receipescoop = v.receipescoop
);

COMMIT;

-- Row counts after seed
SELECT 'vendors' AS tbl, COUNT(*) AS rows FROM public.vendors
UNION ALL SELECT 'categories', COUNT(*) FROM public.categories
UNION ALL SELECT 'dishes', COUNT(*) FROM public.dishes
UNION ALL SELECT 'raw_materials', COUNT(*) FROM public.raw_materials
UNION ALL SELECT 'scoop_config', COUNT(*) FROM public.scoop_config
UNION ALL SELECT 'orders', COUNT(*) FROM public.orders
UNION ALL SELECT 'order_items', COUNT(*) FROM public.order_items
UNION ALL SELECT 'inventory_out', COUNT(*) FROM public.inventory_out
UNION ALL SELECT 'inventory_out_items', COUNT(*) FROM public.inventory_out_items
UNION ALL SELECT 'order_entries', COUNT(*) FROM public.order_entries
UNION ALL SELECT 'order_out', COUNT(*) FROM public.order_out
UNION ALL SELECT 'recipe_entries', COUNT(*) FROM public.recipe_entries
ORDER BY tbl;
